<?php
require_once __DIR__.'/verificar_sesion.php';$db=conexion();$q=trim($_GET['q']??'');
if($q!==''){$like='%'.$q.'%';$stmt=$db->prepare('SELECT p.*,c.nombre AS categoria FROM productos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.nombre LIKE ? OR c.nombre LIKE ? ORDER BY p.id DESC');$stmt->bind_param('ss',$like,$like);}else{$stmt=$db->prepare('SELECT p.*,c.nombre AS categoria FROM productos p LEFT JOIN categorias c ON c.id=p.categoria_id ORDER BY p.id DESC');}
$stmt->execute();$productos=$stmt->get_result();$total=$db->query('SELECT COUNT(*) n FROM productos')->fetch_assoc()['n'];$titulo='Inventario';require __DIR__.'/includes/encabezado.php';?>
<main class="contenido"><h1>Inventario</h1><?php if(isset($_GET['msg'])):?><p class="aviso"><?php echo e($_GET['msg']);?></p><?php endif;?><div class="resumen"><div class="dato"><span><?php echo (int)$total;?></span>Productos</div></div>
<div class="barra-acciones"><form class="buscador"><input type="search" name="q" value="<?php echo e($q);?>" placeholder="Buscar producto o categoría"><button class="boton">Buscar</button></form><a class="boton" href="guardar.php">+ Registrar producto</a></div>
<div class="tabla-scroll"><table><thead><tr><th>Imagen</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Acciones</th></tr></thead><tbody><?php if(!$productos->num_rows):?><tr><td colspan="6">No hay productos.</td></tr><?php endif;?><?php while($p=$productos->fetch_assoc()):?><tr><td class="miniatura"><?php echo imagen_prenda($p['imagen'],$p['nombre']);?></td><td><?php echo e($p['nombre']);?></td><td><?php echo e($p['categoria']??'Sin categoría');?></td><td><?php echo e(precio_texto($p['precio']));?></td><td><?php echo (int)$p['stock'];?></td><td class="acciones"><a class="boton" href="actualizar.php?id=<?php echo (int)$p['id'];?>">Editar</a><form method="post" action="eliminar.php" onsubmit="return confirm('¿Eliminar este producto?')"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="id" value="<?php echo (int)$p['id'];?>"><button class="boton boton-peligro">Eliminar</button></form></td></tr><?php endwhile;?></tbody></table></div></main>
<?php $stmt->close();$db->close();require __DIR__.'/includes/pie.php';?>